import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { authService } from '../services/authService';
import { showNotification } from '../utils/notification';

function SupportTicket() {
  const [tickets, setTickets] = useState([]);
  const [newTicket, setNewTicket] = useState({ subject: '', message: '', priority: 'normal' });
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('new');
  const [selectedTicket, setSelectedTicket] = useState(null);

  const currentUser = authService.getCurrentUser();

  // بارگذاری تیکت‌ها
  useEffect(() => {
    if (currentUser) {
      loadTickets();
    }
  }, [currentUser]);

  const loadTickets = async () => {
    setLoading(true);
    try {
      const result = await dbService.getUserTickets(currentUser.id);
      if (result.success) {
        setTickets(result.data);
      }
    } catch (error) {
      showNotification.error('❌ خطا در بارگذاری تیکت‌ها');
    }
    setLoading(false);
  };

  // ارسال تیکت جدید
  const submitTicket = async () => {
    if (!newTicket.subject.trim() || !newTicket.message.trim()) {
      showNotification.warning('⚠️ لطفاً موضوع و پیام را وارد کنید');
      return;
    }

    setLoading(true);
    try {
      const ticketData = {
        userId: currentUser.id,
        username: currentUser.username,
        subject: newTicket.subject,
        message: newTicket.message,
        priority: newTicket.priority,
        status: 'open',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        replies: []
      };

      const result = await dbService.saveTicket(ticketData);
      if (result.success) {
        showNotification.success('✅ تیکت شما با موفقیت ارسال شد');
        setNewTicket({ subject: '', message: '', priority: 'normal' });
        loadTickets();
        setActiveTab('list');
      }
    } catch (error) {
      showNotification.error('❌ خطا در ارسال تیکت');
    }
    setLoading(false);
  };

  // پاسخ به تیکت
  const addReply = async (ticketId, replyMessage) => {
    if (!replyMessage.trim()) {
      showNotification.warning('⚠️ لطفاً پیام پاسخ را وارد کنید');
      return;
    }

    setLoading(true);
    try {
      const ticket = tickets.find(t => t.id === ticketId);
      if (!ticket) return;

      const updatedReplies = [
        ...(ticket.replies || []),
        {
          userId: currentUser.id,
          username: currentUser.username,
          message: replyMessage,
          createdAt: new Date().toISOString()
        }
      ];

      const result = await dbService.updateTicket(ticketId, {
        replies: updatedReplies,
        updatedAt: new Date().toISOString()
      });

      if (result.success) {
        showNotification.success('✅ پاسخ شما ثبت شد');
        loadTickets();
        setSelectedTicket(null);
      }
    } catch (error) {
      showNotification.error('❌ خطا در ارسال پاسخ');
    }
    setLoading(false);
  };

  // بستن تیکت
  const closeTicket = async (ticketId) => {
    if (!window.confirm('آیا از بستن این تیکت مطمئن هستید؟')) return;

    setLoading(true);
    try {
      const result = await dbService.updateTicket(ticketId, {
        status: 'closed',
        updatedAt: new Date().toISOString()
      });

      if (result.success) {
        showNotification.success('✅ تیکت بسته شد');
        loadTickets();
      }
    } catch (error) {
      showNotification.error('❌ خطا در بستن تیکت');
    }
    setLoading(false);
  };

  // وضعیت تیکت
  const getStatusBadge = (status) => {
    const statusMap = {
      open: { label: 'باز', color: 'bg-green-100 text-green-700' },
      closed: { label: 'بسته', color: 'bg-gray-100 text-gray-700' },
      pending: { label: 'در انتظار', color: 'bg-yellow-100 text-yellow-700' }
    };
    const s = statusMap[status] || statusMap.open;
    return <span className={`px-2 py-1 rounded-full text-xs ${s.color}`}>{s.label}</span>;
  };

  // اولویت تیکت
  const getPriorityBadge = (priority) => {
    const priorityMap = {
      low: { label: 'کم', color: 'bg-blue-100 text-blue-700' },
      normal: { label: 'معمولی', color: 'bg-green-100 text-green-700' },
      high: { label: 'بالا', color: 'bg-orange-100 text-orange-700' },
      urgent: { label: 'فوری', color: 'bg-red-100 text-red-700' }
    };
    const p = priorityMap[priority] || priorityMap.normal;
    return <span className={`px-2 py-1 rounded-full text-xs ${p.color}`}>{p.label}</span>;
  };

  return (
    <div className="max-w-7xl mx-auto p-4">
      <div className="glass-card">
        <h3 className="font-bold text-gray-800 text-xl mb-4 flex items-center">
          <span className="text-blue-600 mr-2">🎫</span> سیستم پشتیبانی
        </h3>

        {/* تب‌ها */}
        <div className="flex gap-2 mb-6 overflow-x-auto">
          <button
            onClick={() => setActiveTab('new')}
            className={`px-4 py-2 rounded-xl transition-all ${
              activeTab === 'new' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white text-gray-600 hover:bg-gray-100'
            }`}
          >
            ✏️ تیکت جدید
          </button>
          <button
            onClick={() => setActiveTab('list')}
            className={`px-4 py-2 rounded-xl transition-all ${
              activeTab === 'list' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white text-gray-600 hover:bg-gray-100'
            }`}
          >
            📋 لیست تیکت‌ها
          </button>
        </div>

        {/* تیکت جدید */}
        {activeTab === 'new' && (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">موضوع</label>
              <input
                type="text"
                value={newTicket.subject}
                onChange={(e) => setNewTicket({ ...newTicket, subject: e.target.value })}
                placeholder="موضوع تیکت را وارد کنید"
                className="w-full p-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">اولویت</label>
              <select
                value={newTicket.priority}
                onChange={(e) => setNewTicket({ ...newTicket, priority: e.target.value })}
                className="w-full p-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="low">کم</option>
                <option value="normal">معمولی</option>
                <option value="high">بالا</option>
                <option value="urgent">فوری</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">پیام</label>
              <textarea
                value={newTicket.message}
                onChange={(e) => setNewTicket({ ...newTicket, message: e.target.value })}
                placeholder="مشکل خود را توضیح دهید..."
                rows="5"
                className="w-full p-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              />
            </div>

            <button
              onClick={submitTicket}
              disabled={loading}
              className="w-full py-3 bg-gradient-to-r from-blue-600 to-blue-500 text-white rounded-xl font-bold hover:scale-105 transition-all disabled:opacity-50"
            >
              {loading ? '⏳ در حال ارسال...' : '📤 ارسال تیکت'}
            </button>
          </div>
        )}

        {/* لیست تیکت‌ها */}
        {activeTab === 'list' && (
          <div>
            {loading ? (
              <div className="text-center py-8 text-gray-400">⏳ در حال بارگذاری...</div>
            ) : tickets.length === 0 ? (
              <div className="text-center py-8 text-gray-400">📭 هیچ تیکتی ثبت نشده است</div>
            ) : (
              <div className="space-y-4">
                {tickets.map((ticket) => (
                  <div key={ticket.id} className="bg-gray-50 rounded-xl p-4 border border-gray-200">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <span className="font-bold text-gray-800">{ticket.subject}</span>
                        {getStatusBadge(ticket.status)}
                        {getPriorityBadge(ticket.priority)}
                      </div>
                      <div className="flex gap-2">
                        <button
                          onClick={() => setSelectedTicket(selectedTicket === ticket.id ? null : ticket.id)}
                          className="px-3 py-1 bg-blue-50 text-blue-600 rounded-lg text-sm hover:bg-blue-100 transition-colors"
                        >
                          {selectedTicket === ticket.id ? '📕 بستن' : '📖 مشاهده'}
                        </button>
                        {ticket.status === 'open' && (
                          <button
                            onClick={() => closeTicket(ticket.id)}
                            className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-sm hover:bg-red-100 transition-colors"
                          >
                            🔒 بستن
                          </button>
                        )}
                      </div>
                    </div>
                    <div className="text-xs text-gray-400 mt-1">
                      {new Date(ticket.createdAt).toLocaleString('fa-IR')}
                    </div>

                    {/* نمایش جزئیات تیکت */}
                    {selectedTicket === ticket.id && (
                      <div className="mt-4 p-4 bg-white rounded-xl border border-gray-200">
                        <p className="text-gray-700 whitespace-pre-wrap">{ticket.message}</p>

                        {/* پاسخ‌ها */}
                        {ticket.replies && ticket.replies.length > 0 && (
                          <div className="mt-4 space-y-3">
                            <h4 className="font-medium text-gray-700">پاسخ‌ها:</h4>
                            {ticket.replies.map((reply, idx) => (
                              <div key={idx} className="bg-blue-50 rounded-lg p-3">
                                <div className="flex items-center justify-between">
                                  <span className="font-medium text-blue-700">{reply.username}</span>
                                  <span className="text-xs text-gray-400">
                                    {new Date(reply.createdAt).toLocaleString('fa-IR')}
                                  </span>
                                </div>
                                <p className="text-gray-700 mt-1">{reply.message}</p>
                              </div>
                            ))}
                          </div>
                        )}

                        {/* فرم پاسخ */}
                        {ticket.status === 'open' && (
                          <div className="mt-4">
                            <textarea
                              id={`reply_${ticket.id}`}
                              placeholder="پاسخ خود را بنویسید..."
                              rows="3"
                              className="w-full p-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                            />
                            <button
                              onClick={() => {
                                const replyInput = document.getElementById(`reply_${ticket.id}`);
                                addReply(ticket.id, replyInput.value);
                                replyInput.value = '';
                              }}
                              className="mt-2 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors"
                            >
                              📤 ارسال پاسخ
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default SupportTicket;
